contracts:
type AuthReceiptV2 = {
  sessionId: string; subject: string; expiresAt: Instant; issuer: string;
  admissionEpochRevision: Revision; configHash: string; clockDomain: string;
  admittedEmailDigest: string; sessionTokenDigest: string;
}; // exact nine fields; digests /^[0-9a-f]{64}$/; positive BIGINT Revision string

type AcquisitionCommand =
  | { kind: 'identify'; commandId: Id; username: string }
  | { kind: 'discover'; commandId: Id; associationId: Id; associationRevision: Revision }
  | { kind: 'recover'; commandId: Id; associationId: Id; associationRevision: Revision; leagueId: Id };
// username exactly existing [a-zA-Z0-9_]{1,100}; command/association IDs are UUID.
// Shared Id preserves the referenced opaque identity domain. No actor/provider,
// context/audience/coverage, budget lane, source URL or policy supplied by caller.
// Same actor+commandId with a different canonical input digest is conflict.

type AdmissionResult =
  | { status: 'pending' | 'joined'; demandId: Id; retryAfterSeconds: number }
  | { status: 'denied' | 'limited' | 'conflict' | 'indeterminate'; reason:
      'admission_unavailable' | 'scope_invalid' | 'budget_exhausted' |
      'command_conflict' | 'authority_unavailable' };
type AdmissionHelperResult = { result: AdmissionResult; decisionTiming: DecisionTiming | null };
// retryAfterSeconds integer1..60; own protected demandId requires nonnull timing.

type DemandProgress =
  | { status: 'pending'; demandId: Id; retryAfterSeconds: number }
  | { status: 'identified'; demandId: Id; lookupCaptureId: Id; providerAccount: ProviderAccount }
  | { status: 'discovery-progress'; demandId: Id; scanId: Id;
      requiredSeasons: number[]; completedSeasons: number[];
      coverage: 'pending' | 'partial' | 'complete' | 'failed' }
  | { status: 'recovery-complete'; demandId: Id }
  | { status: 'denied' | 'unavailable' | 'indeterminate'; reason:
      'admission_unavailable' | 'scope_invalid' | 'demand_expired' | 'source_unavailable' | 'authority_unavailable' };
type DemandProgressHelperResult = { result: DemandProgress; decisionTiming: DecisionTiming | null };
// ProviderAccount is the exact foundation type, no private owner/link status.
// Progress does not contain league/team payload. Those still require BS-P01.

type JobFence = { jobKey: string; workerId: string; attemptCount: number; leaseUntil: Instant };
type AcquisitionClaim =
  | { status: 'idle' | 'limited'; retryAfterSeconds: number }
  | { status: 'claimed'; demandId: Id; fence: JobFence;
      work: { kind: 'calendar-state' } |
            { kind: 'identify'; username: string } |
            { kind: 'discover'; nativeAccountId: NativeId; scanId: Id; requiredSeasons: number[] } |
            { kind: 'recover'; scope: SourceScope; sourceMappingRevisionId: Id } };
// Worker receives only bounded work. Actor/session/digests remain private.
// Missing fresh qualified NFL state starts a bounded existing calendar-state
// step before requiredSeasons is fixed; that step also needs a permit.

type SleeperEndpoint =
  | { family: 'identity'; username: string }
  | { family: 'account-leagues'; nativeAccountId: NativeId; season: number }
  | { family: 'league' | 'rosters' | 'users'; externalLeagueId: NativeId }
  | { family: 'matchups' | 'transactions'; externalLeagueId: NativeId; week: number }
  | { family: 'nfl-state' | 'players' }
  | { family: 'schedule'; season: number }
  | { family: 'scores' | 'weekly-stats'; season: number; week: number };
// Only existing qualified GET routes are encoded server-side. No arbitrary URL,
// method, host, header, account identity or lane. Missing required route denies.

type PermitSource =
  | { kind: 'pre-enrollment'; attemptId: Id; policyQualificationId: Id; policyRevision: Revision }
  | { kind: 'enrolled'; attemptId: Id; scopeId: Id; policyRevision: Revision };
// Pre-enrollment addresses provider_request_attempts and
// provider_request_policy_qualifications.id. Enrolled addresses
// league_roster_resource_attempts and league_resource_policy_qualifications.scope_id.
// The exact tagged branch must match demand purpose and persisted attempt scope;
// no ambiguous OR-join or nonexistent pre-enrollment rosters qualifier.

type PermitRequest =
  | { kind: 'target'; requestId: Id; demandId: Id; source: PermitSource;
      fence: JobFence; endpoint: SleeperEndpoint }
  | { kind: 'existing'; requestId: Id; endpoint: SleeperEndpoint;
      purpose: 'live-score' | 'role-roster' | 'transactions' | 'metadata' | 'historical-import' | 'future-observation' | 'future-preparation';
      connectionId: Id | null; source: PermitSource | null; fence: JobFence | null }
  | { kind: 'retry'; requestId: Id; previousPermitId: Id; source: PermitSource | null; fence: JobFence | null };
// Existing server page reads may have null job fence, but only a source-resolved
// registered scope and allowed family/purpose. No caller-controlled routing.
// Target tagged policy/attempt/scope must exactly match persisted reservation.
// JobFence.attemptCount is a positive integer matching actual job attempt_count;
// no fabricated generation. A null source is only a registered unpersisted read.
// Retry endpoint/scope/actor derive from immutable previous request_context.
// Source-backed retry requires a NEW reserved source.attemptId in the same tagged branch under the same logical
// request/scope/context/policy/mapping and current job lease; never reuse a failed
// attempt. Unpersisted server/global read retry requires source:null.

type PermitResult =
  | { status: 'granted'; permitId: Id; dbSampleAt: Instant; dispatchBefore: Instant;
      remainingDispatchMs: number; httpDeadlineMs: 5000 }
  | { status: 'limited' | 'denied' | 'indeterminate'; reason:
      'cooldown' | 'budget_exhausted' | 'authority_unavailable' | 'scope_invalid' | 'deadline' };
// remainingDispatchMs integer1..1000 computed in DB; no public DTO.
// The transport performs exactly one no-store, redirect-manual fetch after
// conservative monotonic expiry check and confirmed permit commit.

type DemandResultRef = null
  | { kind: 'identity'; captureId: Id }
  | { kind: 'discovery'; scanId: Id }
  | { kind: 'recovery'; status: 'complete' };
type DemandTerminalOutcome = null | 'completed' | 'failed' | 'cancelled' | 'expired';
// Persist command_input_hash separately from semantic scope_hash. Exact actor+
// command identity, input digest and terminal outcome survive source-detail compaction.
// Terminal state is completed|failed|cancelled; expired maps to failed+expired.
// terminal_at is nonnull exactly for terminal demands. After terminal30days,
// compact scope and result_ref to null; never compact live demand details.
// An old compacted retry returns unavailable/demand_expired, never enqueues anew.

type PermitOrigin =
  | { kind: 'target'; demandId: Id; source: PermitSource;
      fence: JobFence; endpoint: SleeperEndpoint }
  | { kind: 'existing'; endpoint: SleeperEndpoint;
      purpose: 'live-score' | 'role-roster' | 'transactions' | 'metadata' | 'historical-import' | 'future-observation' | 'future-preparation';
      connectionId: Id | null; source: PermitSource | null; fence: JobFence | null };
type PermitRequestContext = {
  version: 'sleeper-permit-context-v1'; origin: PermitOrigin;
  resolved: { accessContextId: Id; accessRevision: Revision; audienceId: Id;
              connectionId: Id | null; sourceMappingRevisionId: Id | null };
};
// Exact immutable request_context; origin omits transport requestId. Resolved
// context and mapping come from qualified persisted attempt/source registry,
// never caller authority. Connection/mapping are both present or both null.
// Target and persisted existing-source origin requires the exact tagged source;
// existing unpersisted server/global read has source:null. Retry captures
// its newly reserved attempt/fence after proving the same logical source scope.
// No actor/session/token/email digest or raw provider result is included.
